from fastapi import FastAPI, HTTPException, Response
from fastapi.responses import HTMLResponse

from .persistence import Sighting, SightingStorage


def create_app(storage: SightingStorage) -> FastAPI:
    """Build the full Bird Watcher FastAPI app.

    Endpoints:
        GET /                       — landing page metadata
        GET /health                 — uptime check
        GET /gallery                — recent sightings as JSON (the machine face)
        GET /gallery.html           — the same sightings as a web page (the human face)
        GET /sighting/{id}          — one sighting's metadata
        GET /sighting/{id}/image    — one cropped bird photo, straight from storage

    Args:
        storage: any SightingStorage — the app only knows the contract,
            never which database sits behind it.

    Returns:
        A configured FastAPI app, ready to be served with uvicorn.
    """
    app = FastAPI(title="Bird Watcher", version="0.0.0")

    def to_json(sighting: Sighting) -> dict:
        """One sighting as a JSON-safe dict.

        Bytes can't travel inside JSON, so the photo travels as a link."""
        return {
            "id": sighting.id,
            "timestamp": sighting.timestamp,
            "species": sighting.species,
            "confidence": sighting.confidence,
            "submitted_by": sighting.submitted_by,
            "image_url": f"/sighting/{sighting.id}/image",
        }

    @app.get("/")
    def index() -> dict:
        """Landing page."""
        return {"app": "bird-watcher", "status": "watching"}

    @app.get("/health")
    def health() -> dict:
        """Health check — useful for uptime monitoring."""
        return {"status": "ok"}

    @app.get("/gallery")
    def gallery(species: str | None = None, submitted_by: str | None = None,
                limit: int = 50, offset: int = 0) -> dict:
        """Recent sightings, newest first.

        Filter with ?species= and/or ?submitted_by=, page with ?limit= and ?offset=."""
        sightings = storage.get_sightings(
            species=species, submitted_by=submitted_by, limit=limit, offset=offset
        )
        return {"count": len(sightings), "sightings": [to_json(s) for s in sightings]}

    @app.get("/gallery.html")
    def gallery_page() -> HTMLResponse:
        """The human face: HTML + JavaScript that calls our own JSON API (see Step 9.5).

        We read the file on EVERY request — so edit tutorials/static/gallery.html,
        refresh the browser, and see the change. No restart."""
        return HTMLResponse(find_gallery_html().read_text())

    @app.get("/sighting/{sighting_id}")
    def get_sighting(sighting_id: int) -> dict:
        """One sighting's metadata, without the image bytes."""
        sighting = storage.get_sighting(sighting_id)
        if sighting is None:
            raise HTTPException(status_code=404, detail=f"no sighting #{sighting_id}")
        return to_json(sighting)

    @app.get("/sighting/{sighting_id}/image")
    def get_sighting_image(sighting_id: int) -> Response:
        """Serve one sighting's photo straight from storage."""
        sighting = storage.get_sighting(sighting_id)
        if sighting is None:
            raise HTTPException(status_code=404, detail=f"no sighting #{sighting_id}")

        return Response(content=sighting.image_bytes, media_type="image/jpeg")

    return app


