from pathlib import Path


def find_gallery_html() -> Path:
    """Locate tutorials/static/gallery.html from either world this code runs in.

    The same code runs in two places, and "where am I?" differs:
      - as a notebook cell — no `__file__`, working directory is `tutorials/`
      - as the exported module — `__file__` is `bird_watcher/web_app.py`
    """
    here = Path(__file__).parent if "__file__" in globals() else Path.cwd()

    candidates = [
        here / "static" / "gallery.html",                       # notebook: cwd is tutorials/
        here.parent / "tutorials" / "static" / "gallery.html",  # module: up from bird_watcher/
    ]
    for candidate in candidates:
        if candidate.exists():
            return candidate

    raise FileNotFoundError(f"gallery.html not found — looked in: {[str(c) for c in candidates]}")

