import os

from .persistence import SqliteSightingStorage


def main():
    """Start the Bird Watcher web server — the one command a deploy runs.

    Settings come from environment variables, so the same code runs on a
    laptop and on a server:

        BIRDS_DB          — path to the SQLite file  (default: data/birds.db)
        COOLDOWN_MINUTES  — sighting cooldown        (default: 3)
        PORT              — port to listen on        (default: 8123)
    """
    import uvicorn

    storage = SqliteSightingStorage(
        db_path=os.environ.get("BIRDS_DB", "data/birds.db"),
        cooldown_minutes=int(os.environ.get("COOLDOWN_MINUTES", "3")),
    )

    uvicorn.run(
        create_app(storage),
        host="0.0.0.0",  # answer anyone on the network, not just this machine
        port=int(os.environ.get("PORT", "8123")),
    )
